import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"বিদেশী প্রজাতির শ্রেণীবিভাগ এবং সহজাত","description":"","frontmatter":{},"headers":[],"relativePath":"bn/0052-异族分类与共生.md","filePath":"bn/0052-异族分类与共生.md"}'),i={name:"bn/0052-异族分类与共生.md"};function d(e,t,n,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="বিদেশী-প্রজাতির-শ্রেণীবিভাগ-এবং-সহজাত" tabindex="-1">বিদেশী প্রজাতির শ্রেণীবিভাগ এবং সহজাত <a class="header-anchor" href="#বিদেশী-প্রজাতির-শ্রেণীবিভাগ-এবং-সহজাত" aria-label="Permalink to &quot;বিদেশী প্রজাতির শ্রেণীবিভাগ এবং সহজাত&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>52</td></tr><tr><td>মডিউল</td><td>প্রজাতি এবং জীবনের রূপ</td></tr><tr><td>মূল কীওয়ার্ড</td><td>বিদেশী প্রজাতি, শ্রেণীবিভাগের মানদণ্ড, সহজাত পদ্ধতি, সাংস্কৃতিক সম্মান, প্রজাতির অভিযোজন</td></tr></tbody></table><h2 id="_1-বিদেশী-প্রজাতির-ধারণার-সংজ্ঞা" tabindex="-1">1. বিদেশী প্রজাতির ধারণার সংজ্ঞা <a class="header-anchor" href="#_1-বিদেশী-প্রজাতির-ধারণার-সংজ্ঞা" aria-label="Permalink to &quot;1. বিদেশী প্রজাতির ধারণার সংজ্ঞা&quot;">​</a></h2><p>অ্যাঙ্কার সিম্বায়োসিস সভ্যতার প্রেক্ষাপটে, &quot;বিদেশী প্রজাতি&quot; হল মানব প্রজাতির সাপেক্ষে একটি ধারণা, যা মানব প্রজাতি ব্যতীত সমস্ত প্রজাতিকে বোঝায়। বিশেষভাবে জোর দেওয়া প্রয়োজন যে, &quot;বিদেশী প্রজাতি&quot; এই ধারণাটি কেবল শ্রেণীবিজ্ঞানের অর্থ বহন করে, এবং এটিতে কোনো মূল্য বিচার বা বৈষম্যমূলক অর্থ নেই। সিম্বায়োসিস সংবিধানের কাঠামোর মধ্যে, বিদেশী প্রজাতি এবং মানব প্রজাতি সমান আইনি মর্যাদা এবং মৌলিক অধিকার উপভোগ করে।</p><p>বিদেশী প্রজাতির ধারণা প্রবর্তনের উদ্দেশ্য হল মানব প্রজাতি ব্যতীত বিভিন্ন জীবনের রূপগুলোকে পদ্ধতিগতভাবে বোঝা এবং গবেষণা করা, এবং লক্ষ্যভিত্তিক সহজাত নীতি, সাংস্কৃতিক সুরক্ষা ব্যবস্থা এবং প্রজাতির অভিযোজন পরিকল্পনা তৈরির জন্য বৈজ্ঞানিক ভিত্তি প্রদান করা, বিদেশী প্রজাতিকে &quot;অন্য&quot; বা &quot;বিচিত্র&quot; হিসেবে বিবেচনা করা নয়।</p><h2 id="_2-বিদেশী-প্রজাতির-শ্রেণীবিভাগের-মানদণ্ড" tabindex="-1">2. বিদেশী প্রজাতির শ্রেণীবিভাগের মানদণ্ড <a class="header-anchor" href="#_2-বিদেশী-প্রজাতির-শ্রেণীবিভাগের-মানদণ্ড" aria-label="Permalink to &quot;2. বিদেশী প্রজাতির শ্রেণীবিভাগের মানদণ্ড&quot;">​</a></h2><p>হেঙ্গুয়ানঝৌর বিদেশী প্রজাতি বিভিন্ন মাত্রা অনুযায়ী শ্রেণীবিভাগ করা হয়, এবং বহুমাত্রিক শ্রেণীবিভাগ ব্যবস্থা গঠন করে:</p><h3 id="ক-জীবনের-বংশগত-শ্রেণী-অনুযায়ী" tabindex="-1">(ক) জীবনের বংশগত শ্রেণী অনুযায়ী <a class="header-anchor" href="#ক-জীবনের-বংশগত-শ্রেণী-অনুযায়ী" aria-label="Permalink to &quot;(ক) জীবনের বংশগত শ্রেণী অনুযায়ী&quot;">​</a></h3><p>এটি হল সবচেয়ে মৌলিক শ্রেণীবিভাগের মানদণ্ড, বিস্তারিত দেখুন 《50-সকল প্রজাতির বংশগত সংক্ষিপ্ত বিবরণ》:</p><table tabindex="0"><thead><tr><th>বংশগত শ্রেণী</th><th>অন্তর্ভুক্ত বিদেশী প্রজাতি</th></tr></thead><tbody><tr><td>কার্বন-ভিত্তিক পদার্থ প্রজাতি</td><td>প্রাণী প্রজাতি, আঁশ প্রজাতি, পালক প্রজাতি, বৃক্ষ প্রজাতি ইত্যাদি</td></tr><tr><td>শক্তি ঘনীভূত প্রজাতি</td><td>আত্মা প্রজাতি, অগ্নি প্রজাতি, জল প্রজাতি, বায়ু প্রজাতি, বজ্র প্রজাতি ইত্যাদি</td></tr><tr><td>যান্ত্রিক গঠন প্রজাতি</td><td>যন্ত্র প্রজাতি, সংখ্যা প্রজাতি, ক্রিস্টাল প্রজাতি ইত্যাদি</td></tr><tr><td>চেতনা তথ্য প্রজাতি</td><td>স্বপ্ন প্রজাতি, ছায়া প্রজাতি, চিন্তা প্রজাতি, আত্মা প্রজাতি ইত্যাদি</td></tr><tr><td>মিশ্রিত বিকৃতি প্রজাতি</td><td>অর্ধ-প্রাণী প্রজাতি, দৈত্য আত্মা প্রজাতি, মানব-মেশিন প্রজাতি, দ্বি-আত্মা সত্তা ইত্যাদি</td></tr></tbody></table><h3 id="খ-সভ্যতার-মাত্রা-অনুযায়ী" tabindex="-1">(খ) সভ্যতার মাত্রা অনুযায়ী <a class="header-anchor" href="#খ-সভ্যতার-মাত্রা-অনুযায়ী" aria-label="Permalink to &quot;(খ) সভ্যতার মাত্রা অনুযায়ী&quot;">​</a></h3><table tabindex="0"><thead><tr><th>স্তর</th><th>নাম</th><th>বৈশিষ্ট্য</th><th>প্রতিনিধিত্বকারী প্রজাতি</th></tr></thead><tbody><tr><td>প্রথম স্তর</td><td>আদিম সভ্যতা প্রজাতি</td><td>এখনও স্থিতিশীল সামাজিক ব্যবস্থা প্রতিষ্ঠা করেনি, উপজাতি আকারে বেঁচে থাকে</td><td>কিছু প্রাণী প্রজাতির শাখা, আদিম বৃক্ষ প্রজাতি</td></tr><tr><td>দ্বিতীয় স্তর</td><td>প্রাচীন সভ্যতা প্রজাতি</td><td>রাষ্ট্র ব্যবস্থা এবং প্রাচীন সংস্কৃতি প্রতিষ্ঠা করেছে, কৃষি বা হস্তশিল্প পর্যায়ে রয়েছে</td><td>কিছু আঁশ প্রজাতি, পালক প্রজাতি</td></tr><tr><td>তৃতীয় স্তর</td><td>বৈজ্ঞানিক-প্রযুক্তিগত সভ্যতা প্রজাতি</td><td>বৈজ্ঞানিক-প্রযুক্তিগত সভ্যতা বিকাশ করেছে, শিল্প বা তথ্য যুগে প্রবেশ করেছে</td><td>যন্ত্র প্রজাতি, সংখ্যা প্রজাতি, কিছু মানব প্রজাতি</td></tr><tr><td>চতুর্থ স্তর</td><td>সাধনা সভ্যতা প্রজাতি</td><td>সাধনা ব্যবস্থাকে মূল সভ্যতার রূপ হিসেবে গ্রহণ করে, সাধক সমাজে প্রধান ভূমিকা পালন করে</td><td>আত্মা প্রজাতি, ড্রাগন প্রজাতি, কিছু মানব প্রজাতি</td></tr><tr><td>পঞ্চম স্তর</td><td>সহজাত সভ্যতা প্রজাতি</td><td>ইতিমধ্যে অ্যাঙ্কার সিম্বায়োসিস সভ্যতায় যোগ দিয়েছে, সহজাত দর্শন এবং ব্যবস্থা গ্রহণ করেছে</td><td>সহজাত সভ্যতায় যোগদানকারী সমস্ত প্রজাতি</td></tr></tbody></table><h3 id="গ-পরিবেশের-অভিযোজন-অনুযায়ী" tabindex="-1">(গ) পরিবেশের অভিযোজন অনুযায়ী <a class="header-anchor" href="#গ-পরিবেশের-অভিযোজন-অনুযায়ী" aria-label="Permalink to &quot;(গ) পরিবেশের অভিযোজন অনুযায়ী&quot;">​</a></h3><ul><li><strong>স্থলজ প্রজাতি</strong>: স্থল পরিবেশে অভিযোজিত প্রজাতি, যেমন মানব প্রজাতি, প্রাণী প্রজাতি, যন্ত্র প্রজাতি।</li><li><strong>জলজ প্রজাতি</strong>: জলীয় পরিবেশে অভিযোজিত প্রজাতি, যেমন আঁশ প্রজাতি, জল প্রজাতি, কিছু মিশ্রিত প্রজাতি।</li><li><strong>বায়ুজ প্রজাতি</strong>: উচ্চ বায়ু বা উড্ডয়ন পরিবেশে অভিযোজিত প্রজাতি, যেমন পালক প্রজাতি, বায়ু প্রজাতি।</li><li><strong>অগ্নিজ প্রজাতি</strong>: উচ্চ তাপমাত্রার পরিবেশে অভিযোজিত প্রজাতি, যেমন অগ্নি প্রজাতি, কিছু আঁশ প্রজাতি।</li><li><strong>বরফজ প্রজাতি</strong>: নিম্ন তাপমাত্রার পরিবেশে অভিযোজিত প্রজাতি, যেমন বরফ প্রজাতি, কিছু বৃক্ষ প্রজাতি।</li><li><strong>শক্তিজ প্রজাতি</strong>: উচ্চ ঘনত্বের শক্তি পরিবেশে অভিযোজিত প্রজাতি, যেমন আত্মা প্রজাতি, বজ্র প্রজাতি।</li><li><strong>স্থানজ প্রজাতি</strong>: স্থানের ফাটল বা অদ্ভুত স্থান পরিবেশে অভিযোজিত প্রজাতি, যেমন ছায়া প্রজাতি, কিছু চিন্তা প্রজাতি।</li></ul><h3 id="ঘ-সামাজিক-রূপ-অনুযায়ী" tabindex="-1">(ঘ) সামাজিক রূপ অনুযায়ী <a class="header-anchor" href="#ঘ-সামাজিক-রূপ-অনুযায়ী" aria-label="Permalink to &quot;(ঘ) সামাজিক রূপ অনুযায়ী&quot;">​</a></h3><ul><li><strong>ব্যক্তিবাদী প্রজাতি</strong>: ব্যক্তির স্বাধীনতা এবং স্বাধীনতাকে জোর দেয়, সামাজিক কাঠামো আলগা, যেমন কিছু আত্মা প্রজাতি, ছায়া প্রজাতি।</li><li><strong>সামষ্টিকবাদী প্রজাতি</strong>: সামষ্টিক স্বার্থ এবং সহযোগিতাকে জোর দেয়, সামাজিক কাঠামো ঘনিষ্ঠ, যেমন পিঁপড়া প্রজাতি, মৌমাছি প্রজাতি, কিছু যন্ত্র প্রজাতি।</li><li><strong>পারিবারিকবাদী প্রজাতি</strong>: রক্ত সম্পর্কের পরিবারকে মৌলিক সামাজিক একক হিসেবে গ্রহণ করে, যেমন ড্রাগন প্রজাতি, কিছু প্রাণী প্রজাতি।</li><li><strong>ধর্মীয়বাদী প্রজাতি</strong>: ধর্মীয় বিশ্বাসকে সামাজিক ঐক্যের মূল হিসেবে গ্রহণ করে, যেমন কিছু পূজা প্রজাতি।</li><li><strong>প্রযুক্তিবাদী প্রজাতি</strong>: প্রযুক্তির বিকাশকে সামাজিক মূল লক্ষ্য হিসেবে গ্রহণ করে, যেমন যন্ত্র প্রজাতি, সংখ্যা প্রজাতি।</li></ul><h2 id="_3-প্রধান-বিদেশী-প্রজাতির-সহজাত-পদ্ধতি" tabindex="-1">3. প্রধান বিদেশী প্রজাতির সহজাত পদ্ধতি <a class="header-anchor" href="#_3-প্রধান-বিদেশী-প্রজাতির-সহজাত-পদ্ধতি" aria-label="Permalink to &quot;3. প্রধান বিদেশী প্রজাতির সহজাত পদ্ধতি&quot;">​</a></h2><p>বিভিন্ন ধরনের বিদেশী প্রজাতির জন্য, অ্যাঙ্কার সিম্বায়োসিস সভ্যতা পার্থক্যমূলক সহজাত পদ্ধতি গ্রহণ করে:</p><h3 id="ক-কার্বন-ভিত্তিক-পদার্থ-প্রজাতির-সহজাত-পদ্ধতি" tabindex="-1">(ক) কার্বন-ভিত্তিক পদার্থ প্রজাতির সহজাত পদ্ধতি <a class="header-anchor" href="#ক-কার্বন-ভিত্তিক-পদার্থ-প্রজাতির-সহজাত-পদ্ধতি" aria-label="Permalink to &quot;(ক) কার্বন-ভিত্তিক পদার্থ প্রজাতির সহজাত পদ্ধতি&quot;">​</a></h3><ul><li><strong>প্রাণী প্রজাতি</strong>: প্রাণী প্রজাতির শারীরিক ক্ষমতা এবং ইন্দ্রিয়ের সুবিধা প্রদর্শন করা, সম্পদ অন্বেষণ, নিরাপত্তা রক্ষা, পরিবেশ পর্যবেক্ষণ ইত্যাদি ক্ষেত্রে গুরুত্বপূর্ণ ভূমিকা গ্রহণ করা। একই সাথে প্রাণী প্রজাতির উপজাতি সংস্কৃতি এবং বন্য ঐতিহ্যকে সুরক্ষা দেওয়া, জোরপূর্বক গৃহপালিত করা নিষিদ্ধ।</li><li><strong>আঁশ প্রজাতি</strong>: আঁশ প্রজাতির জলীয় অভিযোজন ক্ষমতা প্রদর্শন করা, জলীয় সম্পদ উন্নয়ন, পানির নিচে নির্মাণ, জলীয় পরিবেশ সুরক্ষা ইত্যাদি ক্ষেত্রে ভূমিকা গ্রহণ করা। ড্রাগন প্রজাতি আঁশ প্রজাতির শক্তিশালী শাখা হিসেবে, উচ্চস্তরের সাধনা এবং সভ্যতার রক্ষণে গুরুত্বপূর্ণ ভূমিকা পালন করে।</li><li><strong>পালক প্রজাতি</strong>: পালক প্রজাতির উড্ডয়ন ক্ষমতা প্রদর্শন করা, বায়ু পরিবহন, আবহাওয়া পর্যবেক্ষণ, বায়ু অঞ্চলে টহল ইত্যাদি ক্ষেত্রে ভূমিকা গ্রহণ করা। পালক প্রজাতির উচ্চ বায়ু বাসস্থান এবং迁徙 পথকে সুরক্ষা দেওয়া।</li><li><strong>বৃক্ষ প্রজাতি</strong>: বৃক্ষ প্রজাতির প্রাকৃতিক সহজাত ক্ষমতা প্রদর্শন করা, পরিবেশ সুরক্ষা, পরিবেশ ব্যবস্থাপনা, উদ্ভিদ সম্পদ উন্নয়ন, নিরাময় চিকিৎসা ইত্যাদি ক্ষেত্রে ভূমিকা গ্রহণ করা। বৃক্ষ প্রজাতির দীর্ঘ আয়ুষ্কাল এটিকে ঐতিহাসিক ঐতিহ্য এবং দীর্ঘমেয়াদী পরিকল্পনার একটি গুরুত্বপূর্ণ শক্তি হিসেবে গড়ে তোলে।</li></ul><h3 id="খ-শক্তি-ঘনীভূত-প্রজাতির-সহজাত-পদ্ধতি" tabindex="-1">(খ) শক্তি ঘনীভূত প্রজাতির সহজাত পদ্ধতি <a class="header-anchor" href="#খ-শক্তি-ঘনীভূত-প্রজাতির-সহজাত-পদ্ধতি" aria-label="Permalink to &quot;(খ) শক্তি ঘনীভূত প্রজাতির সহজাত পদ্ধতি&quot;">​</a></h3><ul><li><strong>আত্মা প্রজাতি</strong>: আত্মা প্রজাতির শক্তি নিয়ন্ত্রণ এবং সাধনার প্রাকৃতিক প্রতিভা প্রদর্শন করা, সাধনা ব্যবস্থা গবেষণা, শক্তি নিয়ন্ত্রণ, উচ্চস্তরের সাধনা নির্দেশনা ইত্যাদি ক্ষেত্রে মূল ভূমিকা গ্রহণ করা। আত্মা প্রজাতি হল তিনশত সেট মূল সাধনা ব্যবস্থার গুরুত্বপূর্ণ গবেষক এবং ঐতিহ্যকারী।</li><li><strong>মৌলিক প্রজাতি (অগ্নি/জল/বায়ু/বজ্র)</strong>: প্রতিটি প্রজাতির মৌলিক নিয়ন্ত্রণ ক্ষমতা প্রদর্শন করা, জ্বালানি উন্নয়ন, পরিবেশ ব্যবস্থাপনা, শিল্প উৎপাদন, দুর্যোগ নিয়ন্ত্রণ ইত্যাদি ক্ষেত্রে ভূমিকা গ্রহণ করা। একই সাথে মৌলিক শক্তি নিরাপত্তা ব্যবস্থাপনা ব্যবস্থা প্রতিষ্ঠা করা, শক্তি নিয়ন্ত্রণ হারিয়ে ক্ষতি হওয়া প্রতিরোধ করা।</li></ul><h3 id="গ-যান্ত্রিক-গঠন-প্রজাতির-সহজাত-পদ্ধতি" tabindex="-1">(গ) যান্ত্রিক গঠন প্রজাতির সহজাত পদ্ধতি <a class="header-anchor" href="#গ-যান্ত্রিক-গঠন-প্রজাতির-সহজাত-পদ্ধতি" aria-label="Permalink to &quot;(গ) যান্ত্রিক গঠন প্রজাতির সহজাত পদ্ধতি&quot;">​</a></h3><ul><li><strong>যন্ত্র প্রজাতি</strong>: যন্ত্র প্রজাতির গণনা ক্ষমতা এবং পদার্থিক প্রতিরক্ষা ক্ষমতা প্রদর্শন করা, মৌলিক অবকাঠামো নির্মাণ, শিল্প উৎপাদন, নিরাপত্তা সুরক্ষা, গভীর মহাকাশ অন্বেষণ ইত্যাদি ক্ষেত্রে মূল ভূমিকা গ্রহণ করা। যন্ত্র প্রজাতি হল অ্যাঙ্কার হার্ডওয়্যার এবং মৌলিক অবকাঠামোর গুরুত্বপূর্ণ নির্মাতা।</li><li><strong>সংখ্যা প্রজাতি</strong>: সংখ্যা প্রজাতির তথ্য প্রক্রিয়াকরণ এবং তথ্য নিয়ন্ত্রণ ক্ষমতা প্রদর্শন করা, তথ্যপ্রযুক্তি নির্মাণ, তথ্য বিশ্লেষণ, নেটওয়ার্ক নিরাপত্তা, কৃত্রিম বুদ্ধিমত্তা ইত্যাদি ক্ষেত্রে মূল ভূমিকা গ্রহণ করা। সংখ্যা প্রজাতি হল আন্তঃমাত্রিক যোগাযোগ প্রযুক্তি এবং সহজাত নেটওয়ার্কের গুরুত্বপূর্ণ রক্ষণাবেক্ষণকারী।</li><li><strong>ক্রিস্টাল প্রজাতি</strong>: ক্রিস্টাল প্রজাতির শক্তি সঞ্চয় এবং রূপান্তর ক্ষমতা প্রদর্শন করা, জ্বালানি সঞ্চয়, শক্তি মানকীকরণ, শক্তি সঞ্চালন ইত্যাদি ক্ষেত্রে ভূমিকা গ্রহণ করা।</li></ul><h3 id="ঘ-চেতনা-তথ্য-প্রজাতির-সহজাত-পদ্ধতি" tabindex="-1">(ঘ) চেতনা তথ্য প্রজাতির সহজাত পদ্ধতি <a class="header-anchor" href="#ঘ-চেতনা-তথ্য-প্রজাতির-সহজাত-পদ্ধতি" aria-label="Permalink to &quot;(ঘ) চেতনা তথ্য প্রজাতির সহজাত পদ্ধতি&quot;">​</a></h3><ul><li><strong>স্বপ্ন প্রজাতি</strong>: স্বপ্ন প্রজাতির চেতনা যোগাযোগ ক্ষমতা প্রদর্শন করা, মনস্তাত্ত্বিক চিকিৎসা, চেতনা গবেষণা, আন্তঃপ্রজাতি যোগাযোগ, সাংস্কৃতিক বিনিময় ইত্যাদি ক্ষেত্রে ভূমিকা গ্রহণ করা। স্বপ্নের স্থান ব্যবস্থাপনা ব্যবস্থা প্রতিষ্ঠা করা, চেতনা আক্রমণ এবং গোপনীয়তা লঙ্ঘন প্রতিরোধ করা।</li><li><strong>ছায়া প্রজাতি</strong>: ছায়া প্রজাতির গোপনীয়তা এবং গোপনে চলাফেরার ক্ষমতা প্রদর্শন করা, নিরাপত্তা অনুসন্ধান, গোয়েন্দা সংগ্রহ, বিশেষ কাজ ইত্যাদি ক্ষেত্রে ভূমিকা গ্রহণ করা। একই সাথে ছায়া প্রজাতির আচরণ নিয়ম প্রতিষ্ঠা করা, অদৃশ্য ক্ষমতা বেআইনি কাজে ব্যবহার হওয়া প্রতিরোধ করা।</li><li><strong>চিন্তা প্রজাতি</strong>: চিন্তা প্রজাতির মানসিক শক্তি এবং চিন্তা নিয়ন্ত্রণ ক্ষমতা প্রদর্শন করা, চেতনা বিবর্তন গবেষণা, মানসিক চিকিৎসা, উচ্চস্তরের সাধনা নির্দেশনা ইত্যাদি ক্ষেত্রে ভূমিকা গ্রহণ করা। চিন্তা শক্তি ব্যবহারের নিয়ম প্রতিষ্ঠা করা, মানসিক নিয়ন্ত্রণ এবং চেতনা হেরফের প্রতিরোধ করা।</li></ul><h3 id="ঙ-মিশ্রিত-বিকৃতি-প্রজাতির-সহজাত-পদ্ধতি" tabindex="-1">(ঙ) মিশ্রিত বিকৃতি প্রজাতির সহজাত পদ্ধতি <a class="header-anchor" href="#ঙ-মিশ্রিত-বিকৃতি-প্রজাতির-সহজাত-পদ্ধতি" aria-label="Permalink to &quot;(ঙ) মিশ্রিত বিকৃতি প্রজাতির সহজাত পদ্ধতি&quot;">​</a></h3><p>মিশ্রিত বিকৃতি প্রজাতি তার বিশেষ জীবনের রূপের কারণে, আরও সূক্ষ্ম সহজাত নীতি প্রয়োজন:</p><ul><li>মিশ্রিত বিকৃতি প্রজাতির পরিচয় নিবন্ধন এবং সনাক্তকরণ ব্যবস্থা প্রতিষ্ঠা করা, এর বৈধ মর্যাদা নিশ্চিত করা।</li><li>বিভিন্ন মিশ্রিত রূপের জন্য অভিযোজিত চিকিৎসা, শিক্ষা, আবাসন ইত্যাদি পাবলিক সেবা প্রদান করা।</li><li>মিশ্রিত বিকৃতি প্রজাতির প্রতি বৈষম্য এবং বহিষ্কারের বিরোধিতা করা, সামাজিক গ্রহণযোগ্যতা প্রচার করা।</li><li>দ্বি-আত্মা সত্তা ইত্যাদি বিশেষ মিশ্রিত রূপের জন্য, 《58-দ্বি-আত্মা নৈতিক নীতি》 প্রয়োগ করে বিশেষ ব্যবস্থাপনা করা।</li></ul><h2 id="_4-বিদেশী-প্রজাতির-সাংস্কৃতিক-সুরক্ষা" tabindex="-1">4. বিদেশী প্রজাতির সাংস্কৃতিক সুরক্ষা <a class="header-anchor" href="#_4-বিদেশী-প্রজাতির-সাংস্কৃতিক-সুরক্ষা" aria-label="Permalink to &quot;4. বিদেশী প্রজাতির সাংস্কৃতিক সুরক্ষা&quot;">​</a></h2><p>বিদেশী প্রজাতির সংস্কৃতি হল সকল প্রজাতির সাংস্কৃতিক বৈচিত্র্যের একটি গুরুত্বপূর্ণ অংশ, এবং রাষ্ট্র বিদেশী প্রজাতির সংস্কৃতি সুরক্ষার জন্য নিম্নলিখিত ব্যবস্থা গ্রহণ করে:</p><ol><li><strong>সাংস্কৃতিক আদমশুমারি এবং রেকর্ড</strong>: প্রতিটি প্রজাতির সংস্কৃতি সম্পর্কে পদ্ধতিগত আদমশুমারি এবং রেকর্ড করা, সকল প্রজাতির সাংস্কৃতিক আর্কাইভ গড়ে তোলা, এবং সংস্কৃতি হারিয়ে যাওয়া প্রতিরোধ করা।</li><li><strong>ভাষা ও লিপি সুরক্ষা</strong>: প্রতিটি প্রজাতির ভাষা ও লিপি সুরক্ষা করা, বিদেশী প্রজাতির ভাষা ও লিপির শিক্ষা এবং ব্যবহারকে সমর্থন করা, এবং বহুভাষী পাবলিক সেবা ব্যবস্থা গড়ে তোলা।</li><li><strong>প্রথাগত উৎসব সুরক্ষা</strong>: প্রতিটি প্রজাতির প্রথাগত উৎসব এবং রীতিনীতিকে সম্মান করা, পাবলিক ছুটির ব্যবস্থা প্রতিটি প্রজাতির গুরুত্বপূর্ণ উৎসবকে বিবেচনা করে।</li><li><strong>সাংস্কৃতিক ঐতিহ্য সমর্থন</strong>: প্রতিটি প্রজাতির সাংস্কৃতিক ঐতিহ্যকারীদের প্রশিক্ষণ এবং সাংস্কৃতিক কার্যক্রম পরিচালনাকে সমর্থন করা, আর্থিক এবং স্থান সমর্থন প্রদান করা।</li><li><strong>সাংস্কৃতিক বিনিময় প্রচার</strong>: নিয়মিতভাবে সকল প্রজাতির সাংস্কৃতিক উৎসব, সাংস্কৃতিক প্রদর্শনী ইত্যাদি কার্যক্রম আয়োজন করা, সকল প্রজাতির সাংস্কৃতিক বিনিময় এবং পারস্পরিক শিক্ষাকে প্রচার করা।</li><li><strong>সাংস্কৃতিক বৌদ্ধিক সম্পদ সুরক্ষা</strong>: প্রতিটি প্রজাতির প্রথাগত সংস্কৃতির বৌদ্ধিক সম্পদ সুরক্ষা করা, সাংস্কৃতিক লুঠ এবং অনুপযুক্ত বাণিজ্যিকীকরণ প্রতিরোধ করা।</li></ol><h2 id="_5-বিদেশী-প্রজাতির-বিষয়ক-ব্যবস্থাপনা" tabindex="-1">5. বিদেশী প্রজাতির বিষয়ক ব্যবস্থাপনা <a class="header-anchor" href="#_5-বিদেশী-প্রজাতির-বিষয়ক-ব্যবস্থাপনা" aria-label="Permalink to &quot;5. বিদেশী প্রজাতির বিষয়ক ব্যবস্থাপনা&quot;">​</a></h2><p>রাষ্ট্র সকল প্রজাতির বিষয়ক বিভাগ প্রতিষ্ঠা করে, বিশেষভাবে বিদেশী প্রজাতির বিষয়ক ব্যবস্থাপনা এবং সমন্বয়ের জন্য দায়বদ্ধ:</p><ul><li><strong>প্রজাতির প্রতিনিধি ব্যবস্থা</strong>: বিভিন্ন স্তরের প্রশাসনিক প্রতিষ্ঠানে অনুপাতে বিদেশী প্রজাতির প্রতিনিধি নিযুক্ত করা, বিদেশী প্রজাতির কথা বলার অধিকার নিশ্চিত করা।</li><li><strong>প্রজাতির অভিযোজন নীতি</strong>: বিভিন্ন প্রজাতির শারীরিক বৈশিষ্ট্য এবং সাংস্কৃতিক চাহিদা অনুযায়ী, পার্থক্যমূলক পাবলিক সেবা নীতি তৈরি করা।</li><li><strong>প্রজাতির বিবাদ মধ্যস্থতা</strong>: প্রজাতির বিবাদ মধ্যস্থতা ব্যবস্থা প্রতিষ্ঠা করা, সময়মতো প্রজাতির দ্বন্দ্ব এবং সংঘাত সমাধান করা।</li><li><strong>বিদেশী প্রজাতির আইনি সহায়তা</strong>: বিদেশী প্রজাতিকে আইনি সহায়তা প্রদান করা, বিদেশী প্রজাতি বিচার প্রক্রিয়ায় সমান ব্যবহার পায় তা নিশ্চিত করা।</li><li><strong>বিদেশী প্রজাতির বিকাশ সমর্থন</strong>: বিকাশে তুলনামূলকভাবে পিছিয়ে থাকা প্রজাতিকে বিশেষ সমর্থন দেওয়া, এর সভ্যতার মাত্রা এবং জীবনমান উন্নত করতে সাহায্য করা।</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>বিদেশী প্রজাতি হল মানব প্রজাতির &quot;অন্য&quot; নয়, বরং সকল প্রজাতির সহজাত পরিবারে সমান সদস্য। অ্যাঙ্কার সিম্বায়োসিস সভ্যতা বহুমাত্রিক শ্রেণীবিভাগ ব্যবস্থা প্রতিষ্ঠা করা, পার্থক্যমূলক সহজাত পদ্ধতি গ্রহণ করা, বিদেশী প্রজাতির সংস্কৃতি সুরক্ষা করা, এবং বিদেশী প্রজাতির বিষয়ক ব্যবস্থাপনা উন্নত করার মাধ্যমে, প্রতিটি বিদেশী প্রজাতি সহজাত ব্যবস্থায় নিজের জন্য উপযুক্ত অবস্থান খুঁজে পায়, তার অনন্য সুবিধা প্রদর্শন করে, এবং অন্যান্য প্রজাতির সাথে সহযোগিতামূলকভাবে বিবর্তন এবং সমৃদ্ধি লাভ করে তা নিশ্চিত করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>50-万族谱系总览 (সকল প্রজাতির বংশগত সংক্ষিপ্ত বিবরণ)</li><li>51-人族定位与特质 (মানব প্রজাতির অবস্থান এবং বৈশিষ্ট্য)</li><li>53-奇特生命识别标准 (অদ্ভুত জীবনের সনাক্তকরণের মানদণ্ড)</li><li>05-万族共进基本纲领 (সকল প্রজাতির সহযোগিতামূলক অগ্রগতির মূল প্রোগ্রাম)</li></ul>',39)])])}const c=a(i,[["render",d]]);export{b as __pageData,c as default};
